#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum PersonTitle {
    /// The `mr` honorific.
    Mr,
    /// The `mrs` honorific.
    Mrs,
    /// The `ms` honorific.
    Ms,
    /// The `miss` honorific.
    Miss,
    /// The `mx` honorific.
    Mx,
    /// The `dr` honorific.
    Dr,
    /// The `prof` honorific.
    Prof,
    /// The `professor` honorific.
    Professor,
    /// The `sir` honorific.
