fn retain_attributes(attributes: &mut Vec<Attribute>) {
    attributes.retain_mut(|attribute| {
        if attribute.path().is_ident("derive") {
            let mut derives = attribute
                .parse_args_with(Punctuated::<Path, syn::Token![,]>::parse_terminated)
